/*
 * Ten applied courses built around the AI "picks and shovels" opportunity:
 * sell useful systems, implementation and domain outcomes instead of trying
 * to build a foundation model. Blueprints keep the catalog maintainable while
 * still producing complete lessons, quizzes and capstone requirements.
 */

function buildCourse(blueprint) {
  const prefix = blueprint.id.split('-').map((part) => part[0]).join('');
  return {
    id: blueprint.id,
    slug: blueprint.id,
    title: blueprint.title,
    description: blueprint.description,
    skillIds: blueprint.skillIds || [],
    category: blueprint.category,
    estimatedHours: blueprint.estimatedHours,
    certificateFee: 5000,
    modules: blueprint.modules.map((module, moduleIndex) => {
      const moduleId = `${prefix}-m${moduleIndex + 1}`;
      return {
        id: moduleId,
        title: `Module ${moduleIndex + 1}: ${module.title}`,
        lessons: [{
          id: `${moduleId}-l1`,
          title: module.lessonTitle,
          content: module.content,
          keyTakeaways: module.takeaways,
        }],
        quiz: {
          id: `${moduleId}-quiz`,
          questions: [
            {
              id: `${moduleId}-q1`,
              question: module.check.question,
              options: module.check.options,
              correctIndex: module.check.correctIndex,
              explanation: module.check.explanation,
            },
            {
              id: `${moduleId}-q2`,
              question: 'Which action best proves practical mastery of this module?',
              options: [
                'Memorising tool names without building anything',
                module.practice,
                'Buying every available AI subscription',
                'Copying a competitor without interviewing users',
              ],
              correctIndex: 1,
              explanation: `Practical mastery requires evidence: ${module.practice.toLowerCase()}.`,
            },
            {
              id: `${moduleId}-q3`,
              question: 'What is the safest professional rule when deploying this workflow for a client?',
              options: [
                'Upload all client data to any free tool',
                'Promise perfect AI accuracy',
                'Use approved data, human review, access controls and documented limitations',
                'Hide automation failures from the client',
              ],
              correctIndex: 2,
              explanation: 'Responsible AI delivery combines permission, privacy, human oversight, security and honest performance boundaries.',
            },
          ],
        },
      };
    }),
    capstone: {
      title: blueprint.capstone.title,
      description: blueprint.capstone.description,
      deliverables: blueprint.capstone.deliverables,
      grading: ['Problem fit and measurable value — 30%', 'Working implementation — 30%', 'Safety and reliability — 20%', 'Sales presentation and documentation — 20%'],
    },
  };
}

